import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])

    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    res: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            res.append((start_date + timedelta(days=i * k)).isoformat())
        return res

    if freq == "WEEKLY":
        days = sorted(wd_map[d] for d in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(res) < count:
            week_monday = week0_monday + timedelta(days=step * k * 7)
            for wd in days:
                d = week_monday + timedelta(days=wd)
                if d >= start_date:
                    res.append(d.isoformat())
                    if len(res) == count:
                        break
            step += 1
        return res

    if freq == "MONTHLY":
        start_month_idx = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(res) < count:
                m_idx = start_month_idx + step * k
                year, m0 = divmod(m_idx, 12)
                month = m0 + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if day <= days_in_month:
                    d = date(year, month, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                step += 1
        else:
            n = int(parts[2])
            target_wd = wd_map[parts[3]]
            while len(res) < count:
                m_idx = start_month_idx + step * k
                year, m0 = divmod(m_idx, 12)
                month = m0 + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                first_day = 1 + (target_wd - first_wd) % 7
                if n == -1:
                    day = first_day + ((days_in_month - first_day) // 7) * 7
                else:
                    day = first_day + (n - 1) * 7
                if day <= days_in_month:
                    d = date(year, month, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                step += 1
        return res

    if freq == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        step = 0
        while len(res) < count:
            year = start_date.year + step * k
            try:
                d = date(year, mm, dd)
            except ValueError:
                step += 1
                continue
            if d >= start_date:
                res.append(d.isoformat())
            step += 1
        return res

    raise ValueError(f"Unsupported rule: {rule}")
